import { rateLimit } from 'express-rate-limit'
const limiter = rateLimit({
  windowMs: 60_000, limit: 100,        // 100 requests per IP per minute
  standardHeaders: 'draft-8', legacyHeaders: false,
  // store: new RedisStore({ ... }),  // share the count across instances
})
app.use('/api', limiter)               // 429 once the window is exhausted

